window.SBL_IGCSE_PPQ = {"topic": "Coastal Fieldwork", "img": "/igcse/geography/learn/past-papers-img/", "lessons": {"IGCF01": {"n": 1, "title": "Why is fieldwork important in geography?", "href": "/igcse/geography/learn/coastal-fieldwork/l01-why-fieldwork"}, "IGCF02": {"n": 2, "title": "Planning: types of data, pilot surveys and risk assessment", "href": "/igcse/geography/learn/coastal-fieldwork/l02-planning-data-and-risk"}, "IGCF03": {"n": 3, "title": "Sampling, transects and avoiding bias", "href": "/igcse/geography/learn/coastal-fieldwork/l03-sampling"}, "IGCF04": {"n": 4, "title": "Coastal enquiry methods: how to collect the data", "href": "/igcse/geography/learn/coastal-fieldwork/l04-data-collection-methods"}, "IGCF05": {"n": 5, "title": "Presenting fieldwork data", "href": "/igcse/geography/learn/coastal-fieldwork/l05-presenting-data"}, "IGCF06": {"n": 6, "title": "Analysing data and drawing conclusions", "href": "/igcse/geography/learn/coastal-fieldwork/l06-analysis-and-conclusions"}, "IGCF07": {"n": 7, "title": "Evaluating the enquiry", "href": "/igcse/geography/learn/coastal-fieldwork/l07-evaluation"}}, "parts": [{"key": "2024-5ai", "paper": "2024", "paperLabel": "June 2024 · Paper 1", "q": 5, "id": "5(a)(i)", "marks": 1, "text": "Identify one piece of equipment used to measure gradient.", "intro": "A group of students has undertaken an enquiry that investigated beach characteristics along a stretch of coastline.", "options": [["A", "calliper"], ["B", "clinometer"], ["C", "compass"], ["D", "quadrat"]], "answer": "B", "type": "mcq", "lesson": "IGCF04", "ms": "AO3 (1 mark) (1)\n\nB (Clinometer)\n\nCannot be A (shape), C (direction) or D (distribution).", "sources": []}, {"key": "2024-5aii", "paper": "2024", "paperLabel": "June 2024 · Paper 1", "q": 5, "id": "5(a)(ii)", "marks": 1, "text": "State one risk the students should have prepared for when carrying out their coastal fieldwork.", "intro": "A group of students has undertaken an enquiry that investigated beach characteristics along a stretch of coastline.", "options": [], "answer": null, "type": "write", "lesson": "IGCF02", "ms": "AO3 (1 mark) (1)\n• Slipping (1)\n• Falling into water (1)\n• Coming into contact with dirty water (1)\n• Getting cold (1)\n• Getting lost (1)\n• Heavy rain / strong winds (1)\n• Sea too deep / waves too strong (1)\n• Tide coming in (1)\n\nNo credit for just stating ‘weather’.\nAccept any other acceptable response.", "sources": []}, {"key": "2024-5b", "paper": "2024", "paperLabel": "June 2024 · Paper 1", "q": 5, "id": "5(b)", "marks": 2, "text": "Study Figure 5a in the Resource Booklet. It shows some data about the pebble length for 10 pebbles measured at site 2. Calculate the range in sediment size at site 2. You must show all your working in the space below.", "intro": "A group of students has undertaken an enquiry that investigated beach characteristics along a stretch of coastline.", "options": [], "answer": null, "type": "write", "lesson": "IGCF05", "ms": "AO4 (2 marks) (2)\n\nAward 1 mark for correct method of working with correct figures and 1 mark for correct answer. 17-4 = 13cm", "sources": [{"src": "2024-q5-p44.jpg", "figs": ["5a", "5b"]}]}, {"key": "2024-5ci", "paper": "2024", "paperLabel": "June 2024 · Paper 1", "q": 5, "id": "5(c)(i)", "marks": 2, "text": "Study Figure 5b in the Resource Booklet. Plot the data for sites 1 and 3, from Figure 5b (shown in the Resource Booklet), on Figure 5c (below).", "intro": "A group of students has undertaken an enquiry that investigated beach characteristics along a stretch of coastline.", "options": [], "answer": null, "type": "draw", "lesson": "IGCF05", "ms": "AO4 (2 marks) (2)\nAward 1 mark for each correct plot.", "sources": [{"src": "2024-q5-p44.jpg", "figs": ["5a", "5b"]}, {"src": "2024-q5-fig5c.jpg", "figs": ["5c"]}]}, {"key": "2024-5cii", "paper": "2024", "paperLabel": "June 2024 · Paper 1", "q": 5, "id": "5(c)(ii)", "marks": 1, "text": "Draw a line of best fit on Figure 5c.", "intro": "A group of students has undertaken an enquiry that investigated beach characteristics along a stretch of coastline.", "options": [], "answer": null, "type": "draw", "lesson": "IGCF06", "ms": "AO4 (1 mark) (1)\nAward 1 mark for correct line of best fit drawn.\n\nThe line drawn needs to have at least 2 plots above the line of best fit and 3 plots below the line of best fit drawn OR be drawn through 4 data plots for credit.\n\nNo credit for curved line of best fit", "sources": [{"src": "2024-q5-fig5c.jpg", "figs": ["5c"]}]}, {"key": "2024-5ciii", "paper": "2024", "paperLabel": "June 2024 · Paper 1", "q": 5, "id": "5(c)(iii)", "marks": 2, "text": "Suggest one reason for the relationship shown on Figure 5c.", "intro": "A group of students has undertaken an enquiry that investigated beach characteristics along a stretch of coastline.", "options": [], "answer": null, "type": "write", "lesson": "IGCF06", "ms": "AO3 (1 mark)/AO4 (1 mark) (2)\n\nAward 1 mark (AO4) for initial point and a further mark for development (AO3) up to a maximum of two marks.\n\n• There is a negative correlation between distance along the coast and pebble size (1) because the longer the pebbles have been in the water the smaller they get (1).\n• Pebble size decreases as you go along the coastline (1) because they have experienced more erosion (1).\n• As one increases the other decreases because there has been more erosion (1) as the pebbles have travelled in the water for longer (1).\nAccept any other acceptable response.", "sources": [{"src": "2024-q5-fig5c.jpg", "figs": ["5c"]}]}, {"key": "2024-5d", "paper": "2024", "paperLabel": "June 2024 · Paper 1", "q": 5, "id": "5(d)", "marks": 3, "text": "Explain one other primary data collection method students might have found useful in their coastal enquiry.", "intro": "A group of students has undertaken an enquiry that investigated beach characteristics along a stretch of coastline.", "options": [], "answer": null, "type": "write", "lesson": "IGCF04", "ms": "AO3 (3 marks) (3)\n\nAward 1 mark for initial point and a further mark for development up to a maximum of two marks.\n\n• Students may find it useful to collect data on beach gradient (1) as this is likely to influence sediment size (1) as smaller sediment will be close to the shoreline and larger sediment near the cliffs (1).\n• Students could collect data on sediment shape (1) as you would expect sediment to become more rounded (1) further along the coastline as it has been exposed to more erosion (1).\n• Students could do a field sketch at each site (1) as it can be useful to have qualitative data collection (1) which will help them to remember the features of the coastal landscape (1).\nAccept any other acceptable response.", "sources": []}, {"key": "2024-5e", "paper": "2024", "paperLabel": "June 2024 · Paper 1", "q": 5, "id": "5(e)", "marks": 8, "text": "You have studied a coastal environment as part of your own geographical enquiry. Evaluate the accuracy and reliability of your data collection methods.", "intro": "A group of students has undertaken an enquiry that investigated beach characteristics along a stretch of coastline.", "options": [], "answer": null, "type": "write", "lesson": "IGCF07", "ms": "AO3 (4 marks)/AO4 (4 marks) (8)\nMarking instructions Markers must apply the descriptors in line with the general marking guidance and the qualities outlined in the level-based mark scheme below.\nIndicative content guidance The indicative content below is not prescriptive, and candidates are not required to include all of it. Other relevant material not suggested below must also be credited. This question is about evaluating the accuracy and reliability of the student’s own data collection methods. The candidate needs to evaluate the strengths and weaknesses of several different data collection techniques they used in their enquiry and reach a judgement on how effective their data collection was overall.\n\nAO3\n• Accuracy is about how correct or incorrect the data written down is.\n• Reliability is about how dependable the data collected is and often relates to having a big enough sample size to make a judgement.\n• Data collection techniques are the methods adopted when collecting data.\n• There are different sampling strategies which have a range of advantages and disadvantages that need to be considered to increase reliability.\n• Consideration of different equipment errors and the impact these might have had on accuracy of data.\n• Consideration of the number of sites and samples taken and the impact these might have on reliability.\n• A judgement about which techniques were reliable and/or accurate.\n• A judgement about overall accuracy and reliability of data collection techniques.\n\nAO4\n• Detail about the specific sampling strategies used of their own data collection techniques.\n• Detail about the site selection for enquiry.\n• Detail about the sample size for each set of data collected.\n• Detail about the equipment used for each technique.\n• Detail about rationale for taking more than one reading for a data type.\nLevel Mark Descriptor\n\n0 No rewardable material.\n\nLevel 1 1–3 • Attempts to apply understanding to deconstruct information but understanding and connections are flawed. An unbalanced or incomplete argument that provides limited synthesis of understanding. Judgements that are supported by limited evidence. (AO3)\n\n• Uses some geographical skills to obtain information with limited relevance and accuracy, which supports few aspects of the argument. (AO4)\n\nLevel 2 4–6 • Applies understanding to deconstruct information and provide some logical connections between concepts. An imbalanced argument that synthesises mostly relevant understanding, but not entirely coherently, leading to judgements that are supported by evidence occasionally. (AO3)\n\n• Uses geographical skills to obtain accurate information that supports some aspects of the argument. (AO4)\n\nLevel 3 7–8 • Applies understanding to deconstruct information and provide logical connections between concepts throughout. A balanced, well-developed argument that synthesises relevant understanding coherently, leading to judgements that are supported by evidence throughout. (AO3)\n• Uses geographical skills to obtain accurate information that supports all aspects of the argument. (AO4)", "sources": []}, {"key": "2023-5a", "paper": "2023", "paperLabel": "June 2023 · Paper 1", "q": 5, "id": "5(a)", "marks": 2, "text": "Describe one way you managed a risk that you identified during your enquiry.", "intro": "You have carried out a geographical enquiry as part of your work on coastal environments. Title of your geographical enquiry", "options": [], "answer": null, "type": "write", "lesson": "IGCF02", "ms": "AO4 (2 marks)\n\nAward 1 mark for a suitable risk identified and 1 further mark for description of how this was managed.\n\n• Falling in the sea (1) was managed by not getting to close the sea with strong tides (1).\n\n• To reduce the risk of exposure (1) I made sure that I had suitable footwear and clothing (1).\n\n• There is a risk of slipping over (1) which can be reduced by wearing appropriate footwear (1).\n\n• There is a risk of getting lost (1) so we went around in groups (1).\n\nAccept any other appropriate response.\n\n(2)", "sources": []}, {"key": "2023-5b", "paper": "2023", "paperLabel": "June 2023 · Paper 1", "q": 5, "id": "5(b)", "marks": 3, "text": "Explain one way you decided on the sites for your data collection.", "intro": "You have carried out a geographical enquiry as part of your work on coastal environments. Title of your geographical enquiry", "options": [], "answer": null, "type": "write", "lesson": "IGCF03", "ms": "AO4 (3 marks)\n\nAward 1 mark for initial point, and a further 2 marks for explanation or development.\nCandidates may refer to how the choices were made on a practical basis, but also in term of sampling strategy.\n• We chose two sites to conduct our fieldwork (1) one which was just after a groyne, and one that was on a section of coastline with no management (1) to see if we could find a difference in beach characteristics (1).\n• We selected three sites along the coastline (1) that were in walking distance (1) as this allowed us time to collect the data one day (1).\n• We used stratified sampling (1) to collect readings from contrasting locations (1) to see how coastal management affects beach characteristics (1).\n\nAccept any other appropriate response.\n\n(3)", "sources": []}, {"key": "2023-5c", "paper": "2023", "paperLabel": "June 2023 · Paper 1", "q": 5, "id": "5(c)", "marks": 4, "text": "Describe two types of data collection method you used during your enquiry.", "intro": "You have carried out a geographical enquiry as part of your work on coastal environments. Title of your geographical enquiry", "options": [], "answer": null, "type": "write", "lesson": "IGCF04", "ms": "AO3 (2 marks) /AO4 (2 marks)\n\nAward 1 mark for identification of a primary or secondary data collection method used and a further mark for development through further description or exemplification.\n\nCandidates can describe any two methods (primary and/or secondary) of data collection that are appropriate to their enquiry.\n\n• I collected data to look at the profile of the beach (1) by using a ranging pole and clinometer to measure changes in angle from shoreline to top of beach (1).\n• I collected data on sediment size (1) by measuring pebbles at different points along the beach (1).\n• I measured longshore drift (1) by throwing an orange into the sea and measuring distance travelled in 5 minutes (1).\n• I drew field sketches (1) to record the landforms/characteristics of each site (1).\n\nAccept any other appropriate response.\n\n(4)", "sources": []}, {"key": "2023-5d", "paper": "2023", "paperLabel": "June 2023 · Paper 1", "q": 5, "id": "5(d)", "marks": 3, "text": "Explain one technique you used to analyse your data.", "intro": "You have carried out a geographical enquiry as part of your work on coastal environments. Title of your geographical enquiry", "options": [], "answer": null, "type": "write", "lesson": "IGCF06", "ms": "AO4 (3 marks)\nAward 1 mark for identification of data analysis technique used, and a further mark for development through further description or exemplification.\n\n• I calculated the mean (1) by adding up each of the pebble size measurements and dividing by 5 (the number of times I recorded data) (1) to try and smooth out any variations in the data (1).\n• Used Spearman’s rank (1) to compare sediment size and shape (1) to determine if the correlation is significant (1).\n• Calculated a percentage (1) as they are relative (1) which means different sets of data can be compared (1).\n• Calculated the interquartile range (1) to remove the outliers in the data (1) in case they caused by human error in data collection (1).\nNo credit awarded for identifying a data presentation technique.\nAccept any other appropriate response.\n\n(3", "sources": []}, {"key": "2023-5e", "paper": "2023", "paperLabel": "June 2023 · Paper 1", "q": 5, "id": "5(e)", "marks": 8, "text": "Study Figure 5a and Figure 5b in the Resource Booklet. They show some information about data presentation from a student’s enquiry. The aim of the student’s enquiry was to investigate changes in coastal features. The student made field sketches of the data collection sites, and collected data on beach profiles and sediment size. Evaluate the effectiveness of the data presentation techniques used by the student.", "intro": "You have carried out a geographical enquiry as part of your work on coastal environments. Title of your geographical enquiry", "options": [], "answer": null, "type": "write", "lesson": "IGCF07", "ms": "AO3 (4 marks) AO4 (4 marks)\n\nMarking instructions Markers must apply the descriptors in line with the general marking guidance and the qualities outlined in the level based mark scheme below.\n\nIndicative content guidance The indicative content below is not prescriptive and candidates are not required to include all of it. Other relevant material not suggested below must also be credited. This question is about the candidates being able to evaluate whether the data presentation techniques used are effective in helping them analyse and identify patterns in the data. The data presentation techniques may be regarded as not appropriate for the data being presented leading to a judgement being made on how helpful they would be in analysis.\n\n• At level 1 candidates will likely describe the data presentation methods that are used and may make simple statements about how they can be used for analysis at the top of the level.\n• At level 2 candidates may describe all of the techniques used as well as making simple statements about how they demonstrate patterns.\n• For level 3 candidates would be expected to make a judgement on the suitability of the presentation techniques and how they establish patterns or not.\nAO3\n• Recognition that the data presentation techniques used are appropriate to the data that is being presented – and can help to identify trends and anomalies.\n• Recognition of the importance of having accurate/specific axis labels on the data presentation techniques.\n• Recognition that there are improvements/alternatives which could increase the usefulness of the data presentation techniques provided.\n• Recognition that there are limitations to the data presentation techniques used.\n• An evaluation of how far the student’s data presentation methods can be trusted may be provided.\nAO4\n• Figure 5a shows a scatter graph comparing distance along the beach and average sediment size.\n• Figure 5a does not make it clear whether ‘distance along beach’ is from shoreline to back of beach (top to bottom) or from one side of the beach to the other (west to east).\n• Figure 5a shows average sediment size but does not give detail about how many data points this is based on.\n• Figure 5b shows a bar graph showing pebble shape and size at site 1 and 10 site.\n• Figure 5b only has site 1 and 10 presented which means 8 sites are not shown on the graph.\n\nLevel Mark Descriptor\n\n0 No rewardable material.\n\nLevel 1 1–3 • Attempts to apply understanding to deconstruct information but understanding and connections are flawed. An unbalanced or incomplete argument that provides limited synthesis of understanding. Judgements that are supported by limited evidence. (AO3)\n\n• Uses some geographical skills to obtain information with limited relevance and accuracy, which supports few aspects of the argument. (AO4)\n\nLevel 2 4–6 • Applies understanding to deconstruct information and provide some logical connections between concepts. An imbalanced argument that synthesises mostly relevant understanding, but not entirely coherently, leading to judgements that are supported by evidence occasionally. (AO3)\n\n• Uses geographical skills to obtain accurate information that supports some aspects of the argument. (AO4)\n\nLevel 3 7–8 • Applies understanding to deconstruct information and provide logical connections between concepts throughout. A balanced, well-developed argument that synthesises relevant understanding coherently, leading to judgements that are supported by evidence throughout. (AO3)\n\n• Uses geographical skills to obtain accurate information that supports all aspects of the argument. (AO4)", "sources": [{"src": "2023-q5-p44.jpg", "figs": ["5a", "5b"]}]}, {"key": "2023R-5a", "paper": "2023R", "paperLabel": "June 2023 · Paper 1R", "q": 5, "id": "5(a)", "marks": 2, "text": "Explain why your fieldwork location was suitable for this enquiry.", "intro": "You have studied a coastal environment as part of your own geographical enquiry. Title of your geographical enquiry", "options": [], "answer": null, "type": "write", "lesson": "IGCF01", "ms": "AO4 (2 marks)\n\nAward 1 mark for a suitable reason and 1 further mark for explanation or development.\n\n• There was a coastline which had different coastal management techniques in different sections (1) which meant that I could compare characteristics (1).\n\n• I wanted to investigate changes in beach profiles (1) and this was the closest beach to our school (1).\n\n• Access to this beach was possible (1) it was not private land (1).\n\nAccept any other appropriate response.\n\n(2)", "sources": []}, {"key": "2023R-5b", "paper": "2023R", "paperLabel": "June 2023 · Paper 1R", "q": 5, "id": "5(b)", "marks": 3, "text": "Explain one quantitative method you chose for data collection.", "intro": "You have studied a coastal environment as part of your own geographical enquiry. Title of your geographical enquiry", "options": [], "answer": null, "type": "write", "lesson": "IGCF04", "ms": "AO4 (3 marks)\n\nAward 1 mark for identification of suitable method, and a further 2 marks for explanation or development.\n\n• Measuring beach features (1) which meant we had to collect quantitative data on beach height and angles of the beach (1) which we could then use to create the beach profile graph (1).\n\n• Measuring pebble size (1) we had to use a ruler (1) and then record the sizes so they could be used to create a graph showing size of pebbles on different sections of the beach (1).\n\nAccept any other appropriate response.\n\n(3)", "sources": []}, {"key": "2023R-5c", "paper": "2023R", "paperLabel": "June 2023 · Paper 1R", "q": 5, "id": "5(c)", "marks": 3, "text": "Explain one advantage of a technique you used to present your fieldwork data.", "intro": "You have studied a coastal environment as part of your own geographical enquiry. Title of your geographical enquiry", "options": [], "answer": null, "type": "write", "lesson": "IGCF05", "ms": "AO4 (3 marks)\nAward 1 mark for identification of a suitable advantage, and a further mark for development through further description or exemplification.\n\n• I used a scattergraph (1) which allowed me to see a correlation between factors (1) which meant I could produce a clear conclusion (1).\n\n• I used graphs to create beach profiles (1) which meant I could easily compare across different sites (1) and recognise any differences (1).\n\nAccept any other appropriate response.\n\n(3", "sources": []}, {"key": "2023R-5d", "paper": "2023R", "paperLabel": "June 2023 · Paper 1R", "q": 5, "id": "5(d)", "marks": 4, "text": "Explain two techniques you used to analyse your data.", "intro": "You have studied a coastal environment as part of your own geographical enquiry. Title of your geographical enquiry", "options": [], "answer": null, "type": "write", "lesson": "IGCF06", "ms": "AO3 (2 marks) /AO4 (2 marks)\n\nAward 1 mark for identification of data analysis technique used and a further mark for development through further description or exemplification.\n\n• I calculated the mean (1) to try and smooth out any variations in the data (1).\n\n• I created a scattergraph of sediment size and distance from the sea to analyse the data for any correlations (1) and identify anomalies/outliers (1).\n\n• I used Spearman’s rank correlation (1) to be able to indicate any strong or weak correlations between my data on beach distance and bedload (1).\n\n• Calculated a percentage (1) which means different sets of data can be compared (1).\n\n• Calculated the interquartile range (1) to remove the outliers in the data (1).\n\nAccept any other appropriate response.\n\n(4)", "sources": []}, {"key": "2023R-5e", "paper": "2023R", "paperLabel": "June 2023 · Paper 1R", "q": 5, "id": "5(e)", "marks": 8, "text": "Study Figure 5a and Figure 5b in the Resource Booklet. They show some information about data collection methods from a student’s enquiry. The aim of the student’s enquiry was to determine the most important factor affecting a beach profile. Evaluate how far the data collection methods used supported the student in achieving their aim.", "intro": "You have studied a coastal environment as part of your own geographical enquiry. Title of your geographical enquiry", "options": [], "answer": null, "type": "write", "lesson": "IGCF07", "ms": "AO3 (4 marks) AO4 (4 marks)\n\nMarking instructions Markers must apply the descriptors in line with the general marking guidance and the qualities outlined in the level based mark scheme below.\n\nIndicative content guidance The indicative content below is not prescriptive and candidates are not required to include all of it. Other relevant material not suggested below must also be credited. This question is about the candidates being able to evaluate whether the data collection methods used were effective in helping the student achieve their aim.\n\n• At level 1 candidates will likely describe the data collection methods that are used and may make simple statements about how they can be used for analysis at the top of the level.\n• At level 2 candidates may describe all of the techniques used as well as making simple statements about how they could be used to by the candidate to reach their aim.\n• For level 3 candidates would be expected to make a judgement on the suitability of the collection methods and how they would support the analysis for the student to be able to achieve their aim.\n\nAO3\n• Recognition of limitations in the data collection/sampling techniques may be flawed in terms of the number of sites and the time of year.\n\n• Recognition that the data collection methods used are appropriate to support a range of data presentation methods.\n\n• Reliability and accuracy of the student’s methods may be evaluated with reference to the potential evaluation, including equipment errors and operator errors.\n\n• Recognition of sampling strategy e.g. random, stratified and/or systematic is important, and could have affected data collected.\n\n• An evaluation of how far the student’s data collection methods would also depend on the accuracy of how they were carried out could also be included.\nAO4\n\n• In this response there would be an expectation for the students to evaluate the different data collection methods and how they relate to later stages of the enquiry (data analysis and reaching conclusions).\n\n• Students should look to identify the appropriateness of data collection methods.\n\n• There could be an evaluation of the lack of secondary data to support primary data.\n\n• A view could be given on how successful or unsuccessful the data collection methods were and how they could be improved to help students gather more effective results.\n\nLevel Mark Descriptor\n\n0 No rewardable material.\n\nLevel 1 1–3 • Attempts to apply understanding to deconstruct information but understanding and connections are flawed. An unbalanced or incomplete argument that provides limited synthesis of understanding. Judgements that are supported by limited evidence. (AO3)\n\n• Uses some geographical skills to obtain information with limited relevance and accuracy, which supports few aspects of the argument. (AO4)\n\nLevel 2 4–6 • Applies understanding to deconstruct information and provide some logical connections between concepts. An imbalanced argument that synthesises mostly relevant understanding, but not entirely coherently, leading to judgements that are supported by evidence occasionally. (AO3)\n\n• Uses geographical skills to obtain accurate information that supports some aspects of the argument. (AO4)\n\nLevel 3 7–8 • Applies understanding to deconstruct information and provide logical connections between concepts throughout. A balanced, well-developed argument that synthesises relevant understanding coherently, leading to judgements that are supported by evidence throughout. (AO3)\n• Uses geographical skills to obtain accurate information that supports all aspects of the argument. (AO4)\nQuestion 6", "sources": [{"src": "2023R-q5-p41.jpg", "figs": ["5a", "5b"]}]}, {"key": "2022-5ai", "paper": "2022", "paperLabel": "June 2022 · Paper 1", "q": 5, "id": "5(a)(i)", "marks": 1, "text": "Study Figure 5a in the Resource Booklet. Identify one type of primary data used by the students.", "intro": "A group of students have undertaken an enquiry that explores how beach characteristics change due to coastal management.", "options": [["A", "local shoreline management plan"], ["B", "field sketches"], ["C", "local historical map"], ["D", "newspaper articles"]], "answer": "B", "type": "mcq", "lesson": "IGCF02", "ms": "AO3 (1 mark)\n\nB field sketch (1)\n\nIt cannot be A, C or D as these are all secondary data sources.\n\n(1)", "sources": [{"src": "2022-q5-p41.jpg", "figs": ["5a", "5b"]}]}, {"key": "2022-5aii", "paper": "2022", "paperLabel": "June 2022 · Paper 1", "q": 5, "id": "5(a)(ii)", "marks": 1, "text": "Name one piece of equipment the students could have used in their enquiry.", "intro": "A group of students have undertaken an enquiry that explores how beach characteristics change due to coastal management.", "options": [], "answer": null, "type": "write", "lesson": "IGCF04", "ms": "AO3 (1 mark)\nAward one mark for suitable piece of equipment.\n\n• Tape measure (1)\n• Clinometer (1)\n• Ranging pole / measuring pole (1)\n• Ruler (1)\n• Camera (1)\n• Phone / tablet (1)\n\nDo not credit pen / paper.\nAccept any other appropriate response.\n\n(1)", "sources": []}, {"key": "2022-5bi", "paper": "2022", "paperLabel": "June 2022 · Paper 1", "q": 5, "id": "5(b)(i)", "marks": 2, "text": "Study Figure 5b which shows some data about beach characteristics at four sites where data was collected. Calculate the mean pebble size at Site 2. Give your answer to one decimal place. You must show all your workings in the space below.", "intro": "A group of students have undertaken an enquiry that explores how beach characteristics change due to coastal management.", "options": [], "answer": null, "type": "write", "lesson": "IGCF05", "ms": "AO4 (2 marks)\nAward one mark for correct working, and one mark for correct answer.\n\n(25+20+22+18)/4 (1) OR 85/4 (1) 21.3 (1)\n\n(2)", "sources": [{"src": "2022-q5-p41.jpg", "figs": ["5a", "5b"]}]}, {"key": "2022-5bii", "paper": "2022", "paperLabel": "June 2022 · Paper 1", "q": 5, "id": "5(b)(ii)", "marks": 1, "text": "State one type of sampling students could have used to choose their data collection sites.", "intro": "A group of students have undertaken an enquiry that explores how beach characteristics change due to coastal management.", "options": [], "answer": null, "type": "write", "lesson": "IGCF03", "ms": "AO3 (1 mark)\nAward one mark for suitable sampling strategy named.\n\n• Random (1)\n• Stratified (1)\n• Systematic (1)\n• Opportunistic (1)\n\n(1)", "sources": []}, {"key": "2022-5biii", "paper": "2022", "paperLabel": "June 2022 · Paper 1", "q": 5, "id": "5(b)(iii)", "marks": 2, "text": "Suggest one reason why the data for Site 1 may not be reliable.", "intro": "A group of students have undertaken an enquiry that explores how beach characteristics change due to coastal management.", "options": [], "answer": null, "type": "write", "lesson": "IGCF07", "ms": "AO3 (2 marks)\nAward one mark for suitable reason and a further mark for explanation, up to a maximum of two marks.\n\n• Data has a much larger range than other sites (1) which suggest an error may have taken place (in data collection) (1).\n• As there are only four pieces of data (1) it would have been better to take more readings to reduce the effect of anomalies (1).\n• The ruler might not be held straight (1) meaning pebble size is recorded incorrectly (1).\nAccept any other appropriate response.\n\n(2)", "sources": []}, {"key": "2022-5ci", "paper": "2022", "paperLabel": "June 2022 · Paper 1", "q": 5, "id": "5(c)(i)", "marks": 2, "text": "Complete the beach profile in Figure 5d below using data highlighted in Figure 5c in the Resource Booklet.", "intro": "A group of students have undertaken an enquiry that explores how beach characteristics change due to coastal management.", "options": [], "answer": null, "type": "draw", "lesson": "IGCF05", "ms": "AO4 (2 marks)\n\nAward one mark for plotting one data point correctly, and a further mark for plotting second data point and the line.\n\nTwo correct data points plotted with no line drawn award one mark.\n\nCompleted version:\n\n(2)", "sources": [{"src": "2022-q5-p42.jpg", "figs": ["5c"]}, {"src": "2022-q5-fig5d.jpg", "figs": ["5d"]}]}, {"key": "2022-5cii", "paper": "2022", "paperLabel": "June 2022 · Paper 1", "q": 5, "id": "5(c)(ii)", "marks": 3, "text": "Explain one advantage of using a line graph to present results.", "intro": "A group of students have undertaken an enquiry that explores how beach characteristics change due to coastal management.", "options": [], "answer": null, "type": "write", "lesson": "IGCF05", "ms": "AO3 (3 marks)\n\nAward 1 mark for identification of a suitable advantage, and a further 2 marks for explanation.\n\n• (Line diagrams) allow patterns to visualized easily (1) and therefore compared to other sites (1) to check if they fit with hypothesis (1).\n\n• (Beach profiles) are easy to construct (1) using Excel / by hand (1) to be able to spot any anomalies in the data (1).\n\n• (Line graphs) are easy to understand (1) which means connections are easily spotted (1) and anomalies can be identified (1).\n\nAccept any other reasonable response.\n\n(3)", "sources": []}, {"key": "2021-5ai", "paper": "2021", "paperLabel": "Summer 2021 · Paper 1", "q": 5, "id": "5(a)(i)", "marks": 1, "text": "Identify the correct definition of systematic sampling.", "intro": "", "options": [["A", "Collecting data at random sites along a coastline."], ["B", "Collecting data every 100m along a coastline."], ["C", "Collecting data from two different coastline."], ["D", "Collecting data from three sites along a coastline."]], "answer": "B", "type": "mcq", "lesson": "IGCF03", "ms": "AO3 (1 mark)\n\nB Collecting data every 100m along a coastline.\n\nThe answer cannot be A (random sampling), C and D (doesn’t state how sampled).\n\n(1)", "sources": []}, {"key": "2021-5aii", "paper": "2021", "paperLabel": "Summer 2021 · Paper 1", "q": 5, "id": "5(a)(ii)", "marks": 1, "text": "Name one piece of equipment you would use to measure beach gradient.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGCF04", "ms": "AO3 (1 mark)\n\nAward 1 mark for a suitable piece of equipment.\n\n• Clinometer (1)\n• Ranging pole (1)\n• Tape measure (1)\n• Meter ruler (1)\nAccept any other appropriate response.\n\n(1)", "sources": []}, {"key": "2021-5aiii", "paper": "2021", "paperLabel": "Summer 2021 · Paper 1", "q": 5, "id": "5(a)(iii)", "marks": 2, "text": "Describe one health and safety risk it is important to be aware of when carrying out fieldwork in a coastal environment.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGCF02", "ms": "AO3 (2 marks)\n\nAward 1 mark for identification of a suitable risk and a further mark for description of why this was important.\n\nFor example:\n• Slipping on rocks (1) as it could lead to injury (1).\n• Getting lost (1) as this could lead to being separated from group (1).\n• Falling in the sea (1) as this could lead to damaged equipment (1).\n• Entering sea with open cuts (1) leading to infection. (1).\n• Lack of awareness of tides (1) leading to being cut off from the beach (1).\n• Danger from falling rocks (1) leading to injuries (1).\n• Variable weather conditions (1) leading to exposure/heat stroke/hypothermia (1).\n• Accessibility to sampling site (1) difficulty getting to site (1) This point could be developed in a number of ways.\n• Large waves (1) knocking people down (1).\n• Awareness of members of the public (1) safeguarding (1).\nAccept any other appropriate response.\n\n(2)", "sources": []}, {"key": "2021-5b", "paper": "2021", "paperLabel": "Summer 2021 · Paper 1", "q": 5, "id": "5(b)", "marks": 8, "text": "Study Figure 5 in the Resource Booklet. It shows information about some design, some data collection methods used, data presentation and a conclusion. The aim of the student’s investigation was to examine change in beach characteristics along the stretch of coastline. Evaluate how far the design and the data collection methods provided reliable evidence for the student’s conclusions.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGCF07", "ms": "AO3 (4 marks) AO4 (4 marks)\n\nMarking instructions Markers must apply the descriptors in line with the general marking guidance and the qualities outlined in the level-based mark scheme below.\n\nIndicative content guidance The indicative content below is not prescriptive, and candidates are not required to include all of it. Other relevant material not suggested below must also be credited. This question is about candidates making a judgement of the data collection methods that have been used and the conclusions made.\nCandidates may note the strengths or weaknesses of the fieldwork presented in Figures 5a and b. Responses could include:\n• Comments on the design regarding sampling method used. (Random sampling used which could lead to anomalies)\n• Comments on the number of data collection sites, relevance of data collected, and the conclusions drawn.\n• Comments could address if the student has met their aim. (Vague comments in conclusions)\n• Comments on the how the conclusions could have been supported by data. (Conclusions are vague)\n• Comments on how anomalies could have affected the results and therefore the conclusion. (Don’t know how data was collected)\n• Comments on other data that could have been collected. (Only 2 sites/size of data set)\n• There is no method or detail around the measurement of river velocity so how reliable are the techniques. For level 2 responses candidates will need to link the evaluation to both data collection methods and conclusions. For level 3 responses there should be a greater depth of evaluation recognising the impacts of the design and the data collection methods on the conclusions made.\nCandidates may refer to data presentation methods to link the data collection and conclusions this should be credited.\nCandidates working at this level must provide an evidenced judgment.\n\nLevel Mark Descriptor\n\n0 No rewardable material.\n\nLevel 1 1–3 • Attempts to apply understanding to deconstruct information but understanding and connections are flawed. An unbalanced or incomplete argument that provides limited synthesis of understanding. Judgements that are supported by limited evidence. (AO3)\n\n• Uses some geographical skills to obtain information with limited relevance and accuracy, which supports few aspects of the argument. (AO4)\n\nLevel 2 4–6 • Applies understanding to deconstruct information and provide some logical connections between concepts. An imbalanced argument that synthesises mostly relevant understanding, but not entirely coherently, leading to judgements that are supported by evidence occasionally. (AO3)\n\n• Uses geographical skills to obtain accurate information that supports some aspects of the argument. (AO4)\nLevel 3 7–8 • Applies understanding to deconstruct information and provide logical connections between concepts throughout. A balanced, well-developed argument that synthesises relevant understanding coherently, leading to judgements that are supported by evidence throughout. (AO3)\n\n• Uses geographical skills to obtain accurate information that supports all aspects of the argument. (AO4)", "sources": [{"src": "2021-q5-p36.jpg", "figs": ["5a"]}, {"src": "2021-q5-p37.jpg", "figs": ["5b"]}]}, {"key": "2019-5ai", "paper": "2019", "paperLabel": "June 2019 · Paper 1", "q": 5, "id": "5(a)(i)", "marks": 1, "text": "Identify the type of sampling method used.", "intro": "A group of students have investigated changes in sediment size along a stretch of coast every 100 metres.", "options": [["A", "systematic"], ["B", "random"], ["C", "stratified"], ["D", "opportunistic"]], "answer": "A", "type": "mcq", "lesson": "IGCF03", "ms": "AO3 (1 mark)\n\nA systematic (1) (1)\n\nB,C and D are all incorrect", "sources": []}, {"key": "2019-5aii", "paper": "2019", "paperLabel": "June 2019 · Paper 1", "q": 5, "id": "5(a)(ii)", "marks": 1, "text": "State one disadvantage of using one of the sampling methods in the question above, a(i).", "intro": "A group of students have investigated changes in sediment size along a stretch of coast every 100 metres.", "options": [], "answer": null, "type": "write", "lesson": "IGCF03", "ms": "AO3 (1 mark) This will depend on the sampling method identified e.g. systematic Poor representation of overall investigation (1) Time constraints (1) Can be biased (1) Can be under representative (1) Unreliable (1) Inaccurate (1)\nAccept any other appropriate response\n\n(1)", "sources": []}, {"key": "2019-5aiii", "paper": "2019", "paperLabel": "June 2019 · Paper 1", "q": 5, "id": "5(a)(iii)", "marks": 2, "text": "Study Figure 5a in the Resource Booklet. It shows sample data on shingle size collected at five sites along a stretch of coastline. Calculate the mean shingle size for the five sites. Give your answer to one decimal place. You must show all your workings in the space below.", "intro": "A group of students have investigated changes in sediment size along a stretch of coast every 100 metres.", "options": [], "answer": null, "type": "write", "lesson": "IGCF05", "ms": "AO4 (2 mark)\n\nCorrect method of working, showing addition, and then division by 5 (1) and one mark for the correct mean, written to one decimal place, 18.3 (1)\n\n(2)", "sources": [{"src": "2019-q5-p43.jpg", "figs": ["5a"]}]}, {"key": "2019-5aiv", "paper": "2019", "paperLabel": "June 2019 · Paper 1", "q": 5, "id": "5(a)(iv)", "marks": 2, "text": "Using the data in Figure 5a (in the Resource Booklet), complete Figure 5b below for sites 1 and 4.", "intro": "A group of students have investigated changes in sediment size along a stretch of coast every 100 metres.", "options": [], "answer": null, "type": "draw", "lesson": "IGCF05", "ms": "AO4 (2 mark)\nAward 1 mark for each correct bar. To be awarded the mark for the first bar, line must be drawn be- tween 21-22. The second bar needs to be right on the line. Shading is not required.\n\n(2)", "sources": [{"src": "2019-q5-p43.jpg", "figs": ["5a"]}, {"src": "2019-q5-fig5b.jpg", "figs": ["5b"]}]}, {"key": "2019-5av", "paper": "2019", "paperLabel": "June 2019 · Paper 1", "q": 5, "id": "5(a)(v)", "marks": 1, "text": "Mark an x in the box on Figure 5b which represents the site with the anomalous result.", "intro": "A group of students have investigated changes in sediment size along a stretch of coast every 100 metres.", "options": [], "answer": null, "type": "draw", "lesson": "IGCF06", "ms": "AO4 (1 mark) One mark for an ‘x’ in box 5\n\n(1)", "sources": [{"src": "2019-q5-fig5b.jpg", "figs": ["5b"]}]}, {"key": "2019-5avi", "paper": "2019", "paperLabel": "June 2019 · Paper 1", "q": 5, "id": "5(a)(vi)", "marks": 2, "text": "Suggest one possible explanation for this anomaly.", "intro": "A group of students have investigated changes in sediment size along a stretch of coast every 100 metres.", "options": [], "answer": null, "type": "write", "lesson": "IGCF06", "ms": "AO3 (2 mark)\n\nAward 1 mark for an initial reason, and a further mark for extension of this point.\n\nE.g.\n\nHuman error with the equipment used to measure sediment /calcu- lation of the mean / selection of the sample to be measured (1) which meant that the sediment appeared bigger than it really was\n(1)\n\nThe sample could have been taken from an area that is protected from the action of the waves / near groynes (1) which means that less would have taken place at this site (1)\n\nSite 5 may have experienced a recent rockfall (1) which meant that the sample was larger / less eroded than the other sites (1)\nAccept any other appropriate response (2)", "sources": [{"src": "2019-q5-fig5b.jpg", "figs": ["5b"]}]}, {"key": "2019-5b", "paper": "2019", "paperLabel": "June 2019 · Paper 1", "q": 5, "id": "5(b)", "marks": 3, "text": "To extend the coastal study, students were asked to use one other primary data method. Explain one other primary data method they might have used.", "intro": "A group of students have investigated changes in sediment size along a stretch of coast every 100 metres.", "options": [], "answer": null, "type": "write", "lesson": "IGCF04", "ms": "AO3 (3 mark)\nAward 1 mark for identification of primary data method and award 2 further marks for development of explanation\nCandidates could identify a number of sources of primary data to help them extend their study including:\nAnnotated field sketches (1) candidates can draw and annotate field sketches (1) to help establish landforms and features on the coast\n(1) Beach profile (1) candidates can use a ranging pole and a clinometer (1) to measure the changes in gradient of the beach (1) Sediment shape at each sample point candidates could take a ran- dom sample (1) and measure the longest axis of the pebble (1) they could use a roundness index or chart to categorise their findings\n\nAccept any other appropriate response\n\n(3)", "sources": []}, {"key": "2019-5c", "paper": "2019", "paperLabel": "June 2019 · Paper 1", "q": 5, "id": "5(c)", "marks": 8, "text": "You have studied coastal environments for your geographical enquiry. Evaluate how successful your chosen data analysis methods were in answering your geographical enquiry question.", "intro": "A group of students have investigated changes in sediment size along a stretch of coast every 100 metres.", "options": [], "answer": null, "type": "write", "lesson": "IGCF07", "ms": "AO3 (4 marks) AO4 (4 marks)\n\nMarking instructions Markers must apply the descriptors in line with the general marking guidance and the qualities outlined in the level based mark scheme below.\nAO3\n• Accuracy is about making judgements about how close conclusions are to the actual changes occurring in the coastal environment where the fieldwork was carried out.\n• Recognition of the extent to which there were equipment errors, e.g. faulty or uncalibrated equipment, and/or operator errors, e.g. misinterpreting the data being recorded, and how this might have affected that might have affected whether they were able to answer their enquiry questions.\n• Recognition of whether there were issues with the design of the data collec- tion and/or sampling methodologies, which may be flawed in terms of the lo- cation/number of sites (spatial), the time of year (temporal), or the equipment chosen.\n\nAO4\n\n• There is evidence of using different skills and techniques to measure changes in coastal environments.\n\n• There is evidence of using different skills and techniques to reach conclusions about changes occurring in coastal environment.\n\n• There is evidence of using different skills and techniques to evaluate conclu- sions about changes occurring in a coastal environment.\n\n• There is evidence of own fieldwork conclusions, i.e. reference to field data col- lected by the student.\n\nThis question is about the candidates making a judgement of the success of their data analysis techniques. Candidates are expected to make a judgement. Candi- dates should identify strengths, weaknesses, alternatives ways of analysing the data\n\nIn this response there would be an expectation for the candidates to evaluate a number of different data analysis techniques.\n\nCandidates should look to identify the appropriateness of data analysis tech- niques.\nA view should be given on how successful or unsuccessful the data analysis tech- niques were and how they could be improved to help candidates understand the data collected more effectively For level 2 responses the candidate response will need to link to the evaluation to their study directly. For level 3 response there should be a greater depth of evaluation. Recognition of whether or not the data analysis was less successful because of the way it was designed/technique used. How far data analysis helped draw a significant conclusion for the study An evaluation of how far the outcomes can be trusted (or repeated to obtain the same results).\n\nLevel Mark Descriptor\n\n0 No rewardable material.\n\nLevel 1 1–3 • Attempts to apply understanding to deconstruct information but un- derstanding and connections are flawed. An unbalanced or incomplete argument that provides limited synthesis of understanding. Judge- ments that are supported by limited evidence. (AO3)\n\n• Uses some geographical skills to obtain information with limited rele- vance and accuracy, which supports few aspects of the argument. (AO4)\n\nLevel 2 4–6 • Applies understanding to deconstruct information and provide some logical connections between concepts. An imbalanced argument that synthesises mostly relevant understanding, but not entirely coherently, leading to judgements that are supported by evidence occasionally. (AO3)\n\n• Uses geographical skills to obtain accurate information that supports some aspects of the argument. (AO4)\n\nLevel 3 7–8 • Applies understanding to deconstruct information and provide logical connections between concepts throughout. A balanced, well-devel- oped argument that synthesises relevant understanding coherently, leading to judgements that are supported by evidence throughout. (AO3)\n\n• Uses geographical skills to obtain accurate information that supports all aspects of the argument. (AO4)", "sources": []}, {"key": "2019R-5ai", "paper": "2019R", "paperLabel": "June 2019 · Paper 1R", "q": 5, "id": "5(a)(i)", "marks": 1, "text": "Identify one risk that the students may identify when undertaking a risk assessment for this investigation.", "intro": "A group of students have investigated processes and landforms along a stretch of coastline.", "options": [], "answer": null, "type": "write", "lesson": "IGCF02", "ms": "AO3 (1 mark)\n\nAward 1 mark for any reasonable risk in the context of this environment:\n\n• Falling in the sea / drowning (1)\n• Exposure / sunburn (1)\n• Slips / trips / bumps (1)\n• Fast flowing currents / powerful tides (1)\n• Infection from water / diseases / polluted water (1)\n• Animals in the water (1)\n• Steep ground / cliffs / cliff / rock falls (1)\n• Deep water (1)\n• Getting lost (1)\n\nAccept any other appropriate response.\n\nReject inaccurate measurements as not part of risk (1) assessment.", "sources": []}, {"key": "2019R-5aii", "paper": "2019R", "paperLabel": "June 2019 · Paper 1R", "q": 5, "id": "5(a)(ii)", "marks": 1, "text": "State one way that this risk could be managed.", "intro": "A group of students have investigated processes and landforms along a stretch of coastline.", "options": [], "answer": null, "type": "write", "lesson": "IGCF02", "ms": "AO3 (1 mark)\nAward 1 mark for any reasonable risk in the context of what was identified in (5ai):\n\n• Wearing strong shoes / walking boots (1)\n• Wear lots of layers to keep warm (1)\n• Check the weather forecast (1)\n• Checking local requirements / plans etc (1)\n• Waking with care (1)\n• Working in groups (1)\n• Wearing lifejacket / life vest (1)\n• Use a shallower / slower part of sea (1)\n• Wearing a helmet / void working too close to the cliffs (1)\n• Stay away from waves (1)\n• Choose a safer location to work in (1).\n• Accept any other appropriate response.\n\nReject approaches that do not match (5ai). (1)", "sources": []}, {"key": "2019R-5aiii", "paper": "2019R", "paperLabel": "June 2019 · Paper 1R", "q": 5, "id": "5(a)(iii)", "marks": 2, "text": "Study Figure 5a in the Resource Booklet. It shows some sample data about shingle size along a stretch of coastline. Calculate the mean shingle size across the five sites. Give your answer to one decimal place. You must show all your workings in the space below.", "intro": "A group of students have investigated processes and landforms along a stretch of coastline.", "options": [], "answer": null, "type": "write", "lesson": "IGCF05", "ms": "AO4 (2 marks)\n\nAward 1 mark for:\n\nCorrect method of working, showing addition, e.g. 83.7 or\n8.1+14.5+16.1+15.0+30.0 (1)\n\nCorrect mean, written to one decimal place, 16.7 (1).\n\n(2) Reject answer to 2dp, i.e. 16.74", "sources": [{"src": "2019R-q5-p43.jpg", "figs": ["5a"]}]}, {"key": "2019R-5aiv", "paper": "2019R", "paperLabel": "June 2019 · Paper 1R", "q": 5, "id": "5(a)(iv)", "marks": 2, "text": "Complete Figure 5b below for sites 1 and 4 using data in Figure 5a (in the Resource Booklet).", "intro": "A group of students have investigated processes and landforms along a stretch of coastline.", "options": [], "answer": null, "type": "draw", "lesson": "IGCF05", "ms": "AO4 (2 marks)\nAward 1 mark for each correct bar. To be awarded the mark for the first bar, line must be drawn between 8-9. The second bar needs to be right on the line. Site 1=8.4 Site 4=15.0\n\nNote width of bars doesn’t matter. There is no need for bars to be (2) shaded.", "sources": [{"src": "2019R-q5-p43.jpg", "figs": ["5a"]}, {"src": "2019R-q5-fig5b.jpg", "figs": ["5b"]}]}, {"key": "2019R-5av", "paper": "2019R", "paperLabel": "June 2019 · Paper 1R", "q": 5, "id": "5(a)(v)", "marks": 2, "text": "Site 5 shows an anomalous result. Suggest one possible explanation for this.", "intro": "A group of students have investigated processes and landforms along a stretch of coastline.", "options": [], "answer": null, "type": "write", "lesson": "IGCF06", "ms": "AO3 (2 mark)\n\nAward 1 mark for an initial reason, and a further mark for extension of this point.\n\nE.g.\n\n• Human error with the equipment used to measure shingle /calculation of the mean / selection of the sample to be measured (1) which meant that the sediment appeared bigger than it really was (1).\n• The sample could have been taken from an area that is protected from the action of the waves / near groynes (1) which means that a different energy profile would have affected this site (1).\n• Site 5 may have experienced a recent rockfall (1) which meant that the sample was larger / less eroded than the other sites (1).\n• A change in the direction of coast (1) causing different sizes of sediment to be deposited created the anomaly (1).\n• Human activities at the coast, e.g. tourism / beach management / replenishment (1) may have resulted on the sediment being moved from one location to another (1).\n\nAccept any other appropriate response.\n\n(2)", "sources": [{"src": "2019R-q5-p43.jpg", "figs": ["5a"]}, {"src": "2019R-q5-fig5b.jpg", "figs": ["5b"]}]}, {"key": "2019R-5b", "paper": "2019R", "paperLabel": "June 2019 · Paper 1R", "q": 5, "id": "5(b)", "marks": 4, "text": "To extend the coastal study, students were asked to use one additional quantitative and one qualitative technique. Describe the two additional fieldwork techniques the students may have selected.", "intro": "A group of students have investigated processes and landforms along a stretch of coastline.", "options": [], "answer": null, "type": "write", "lesson": "IGCF04", "ms": "AO4 (4 mark)\n\nAward marks for a description of the technique (1) and a further mark for a developed description (1) Quantitative:\n• A beach profile would be completed at each site (1) at each site ranging poles are placed at the top and bottom of the beach (1) Qualitative:\n\n• Field sketches can be used to record the main features of the beach profile at different sites (1) this will help the students identify differences (1)\n\nAccept any other appropriate response.\n\n(4)", "sources": []}, {"key": "2019R-5c", "paper": "2019R", "paperLabel": "June 2019 · Paper 1R", "q": 5, "id": "5(c)", "marks": 8, "text": "You have studied a coastal environment as part of your own geographical enquiry. Evaluate the effectiveness of the data collection methods in responding to the purpose of the study.", "intro": "A group of students have investigated processes and landforms along a stretch of coastline.", "options": [], "answer": null, "type": "write", "lesson": "IGCF07", "ms": "AO3 (4 marks) AO4 (4 marks)\n\nMarking instructions Markers must apply the descriptors in line with the general marking guidance and the qualities outlined in the level based mark scheme below.\n\nIndicative content guidance The indicative content below is not prescriptive and candidates are not required to include all of it. Other relevant material not suggested below must also be credited.\nAO3\n• Recognition of the extent to which there were equipment errors, e.g. faulty or uncalibrated equipment, and/or operator errors, e.g. misinterpreting the data being recorded, and how this might have affected that might have affected whether they were able to answer their enquiry questions.\n• Recognition of whether there were issues with the design of the data collection and/or sampling methodologies, which may be flawed in terms of the location/number of sites (spatial), the time of year (temporal), or the equipment chosen.\n• Accuracy is about making judgements about how close conclusions are to the actual changes occurring in the river environment where the fieldwork was carried out.\n\nAO4\n\n• There is evidence of using different skills and techniques to measure changes in a coastal environment – both design and techniques.\n\n• There is evidence of using different skills and techniques to reach conclusions about changes occurring in a coastal environment.\n\n• There is evidence of own fieldwork conclusions, i.e. reference to field data collected by the student.\n\nIf the enquiry question isn’t present do not penalise.\n\n• In this response there would be an expectation for the students to evaluate a number of different data collection techniques.\n• This should an evaluation of primary and secondary data as appropriate.\n• Students should look to identify the appropriateness of data collection techniques.\n• A view should be given on how successful or unsuccessful the data collection techniques were and how they could be improved to help students gather more effective results.\n• For level 2 responses the student response will need to link to the evaluation to their study directly.\n• For level 3 response there should be a greater range or depth of techniques evaluated.\n• Recognition of whether or not the data collection was less successful because of the way it was designed.\n• Recognition of any faults in equipment or human error.\n• How far data-collection methods used produced reliable results\n\n• An evaluation of how far the outcomes can be trusted (or repeated to obtain the same results).\nLevel Mark Descriptor\n\n0 No rewardable material.\n\nLevel 1 1–3 • Attempts to apply understanding to deconstruct information but understanding and connections are flawed. An unbalanced or incomplete argument that provides limited synthesis of understanding. Judgements that are supported by limited evidence. (AO3)\n\n• Uses some geographical skills to obtain information with limited relevance and accuracy, which supports few aspects of the argument. (AO4)\n\nLevel 2 4–6 • Applies understanding to deconstruct information and provide some logical connections between concepts. An imbalanced argument that synthesises mostly relevant understanding, but not entirely coherently, leading to judgements that are supported by evidence occasionally. (AO3)\n\n• Uses geographical skills to obtain accurate information that supports some aspects of the argument. (AO4)\n\nLevel 3 7–8 • Applies understanding to deconstruct information and provide logical connections between concepts throughout. A balanced, well- developed argument that synthesises relevant understanding coherently, leading to judgements that are supported by evidence throughout. (AO3)\n\n• Uses geographical skills to obtain accurate information that supports all aspects of the argument. (AO4)", "sources": []}]};
